head.script:
// 테스트 설명, 유효성 값 설정
//  ★ _1 : 기본 옵션(popupUrl, header, delim) + options 파라미터 공통 / @spec. description 은 분리 샘플 공통.
scwin.tData = {
    "description" : "[gridView > M > readCSV]<br/>CSV 형식의 파일을 업로드하여 GridView 의 데이터로 설정합니다.",
    "validation" : [
        "JDK 1.5 이상에서 사용할 수 있으며 GridView 에 DataList 가 바인딩 되어 있어야 합니다.",
        "options(필수) 파라미터로 CSV 데이터 업로드 옵션을 객체로 설정합니다.",
        "업로드 옵션을 기본값으로만 설정할 경우 빈 객체({})로 설정해야 합니다.",
        "popupUrl(선택) 파라미터로 CSV 파일 선택 팝업창의 경로(URL)를 설정합니다.",
        "CSV 파일 선택 팝업창을 제공 화면 대신 커스텀 화면으로 바꾸는 경우에 설정하며 규약에 맞게 구현하여야 합니다.",
        "popupUrl(선택) 파라미터값을 설정하지 않으면 엔진 기본 팝업창 경로(uiplugin/grid/upload/csvfileUpload.html)가 적용됩니다.",
        "header(선택) 파라미터로 CSV 데이터의 첫번째 Row 를 Header 로 처리하여 무시할지 설정합니다.",
        "header(선택) 파라미터를 '0' 으로 설정 시 첫번째 Row 부터 CSV 데이터로 처리합니다.",
        "header(선택) 파라미터를 '1' 로 설정 시 첫번째 Row 를 Header 로 처리하여 무시합니다.",
        "header(선택) 파라미터를 생략하면 기본값 '1' 로 동작합니다.",
        "startRowIndex 파라미터가 설정되면 header 파라미터는 무시됩니다.",
        "startRowIndex(선택) 파라미터로 CSV 파일에서 데이터가 시작되는 Row 의 번호를 설정합니다.",
        "startRowIndex(선택) 파라미터를 생략하면 기본값 0 으로 동작합니다.",
        "delim(선택) 파라미터로 CSV 데이터의 Column 을 구분하는 문자를 설정합니다.",
        "delim(선택) 파라미터를 생략하면 기본값 ',' 로 동작합니다.",
        "CSV 데이터의 Column 을 구분하는 문자의 기본값이 saveCSV() 메소드는 ';' 이고, readCSV() 메소드는 ',' 이므로 주의하여야 합니다.",
        "readCSV() 메소드의 기본 서블릿은 'csvToXML.wq' 이고, saveCSV() 메소드의 기본 서블릿은 'xmlToCSV.wq' 입니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 : DataList 가 바인딩된 4 Column GridView 를 동적 생성한다.
//  · readCSV 는 DataList 바인딩이 전제 조건이므로 dataList 속성을 반드시 설정한다.
scwin.comp_init = async function () {
    // 기존 target / DataList 정리
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove(dlt_bind.id);
    }
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제]\n- name1~name4 4개 Column 그리드에 초기 데이터 4행(col1_1 ~ col4_4)이 바인딩되어 있음\n- 테스트용 CSV 는 TSQA/src/sample/gridView/data/upload/ts_gridView_M_readCSV_1/ 아래 2개 (쉼표 파일 _upload.csv , 세미콜론 파일 _upload_semicolon.csv)\n- 두 파일 모두 0행이 Header(name1~name4), 1~3행이 데이터(csvA1~csvC4)\n[절차]\n1. par 옵션(popupUrl / header / delim / startRowIndex) 값을 선택한다\n2. readCSV 버튼을 클릭한다\n3. 열린 팝업창에서 CSV 파일을 선택하고 File Upload 를 실행한다\n4. 업로드결과확인 버튼을 클릭한다\n5. (업로드와 무관) 기본서블릿확인 버튼을 클릭한다\n[확인]\n- 2번에서 popupUrl 미설정이면 엔진 기본 팝업창(uiplugin/grid/upload/csvfileUpload.html), 설정이면 커스텀 팝업 화면(/sample/common_link/gridView_M_readCSV_popup_1.xml)이 열리는지 확인\n- 2번 직후 결과창에 팝업창 종류와 실제 열린 경로, 팝업창에 렌더된 delim / header / 데이터 시작 Row 가 출력됨\n- 4번 출력에서 GridView 에 실제 반영된 Row 수와 데이터를 확인\n- 5번 출력에서 readCSV / saveCSV 의 기본 서블릿 경로를 확인"', '', 'label1');

    // DataList 생성 (col1~col4 / 4행)
    await $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성 (DataList 바인딩)
    let cList = $c.gcm.createCList({
        dataList: "data:" + dlt_bind.id
    });
    await $c.gcm.createBasicGridView(cList);
}



// par 옵션값으로 readCSV options 객체를 구성한다.
//  · 선택(필수여부 N) 파라미터는 미설정(빈값) 이면 객체에 담지 않아 생략되도록 한다.
//  · 모든 파라미터가 미설정이면 빈 객체({}) 가 전달된다.
scwin.buildOptions = function () {
    let options = {};
    let v;

    v = par_popupUrl.getValue();
    if (v !== "") options.popupUrl = v;

    v = par_header.getValue();
    if (v !== "") options.header = v;

    v = par_delim.getValue();
    if (v !== "") options.delim = v;

    v = par_startRowIndex.getValue();
    if (v !== "") options.startRowIndex = Number(v);

    return options;
}



// readCSV 실행
//  · 설정한 옵션값을 그대로 되출력하지 않고, 실제로 열린 CSV 파일 선택 팝업창에 렌더된 값을 읽어 출력한다.
scwin.btn_readCSV_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    target1.readCSV(scwin.buildOptions());

    setTimeout(scwin.printUploadState, 1200);
}



// 실제로 열린 CSV 파일 선택 팝업창의 document 를 반환한다.
//  · wframe 적용 시 화면 내 레이어(부모 문서), 미적용 시 window 이름 csvupWindow 인 별도 팝업창이다.
//  · 별도 팝업창은 로딩이 끝나기 전까지 about:blank 이므로 로딩 중임을 알린다.
scwin.getUploadDoc = function () {
    if (document.querySelector("input[name='filename']") !== null) {
        return { "doc" : document, "kind" : "화면 내 레이어(wframe)", "url" : document.location.href };
    }

    let objWin = window.open("", "csvupWindow");
    if (objWin === null || objWin.closed) return null;
    if (objWin.location.href === "about:blank") return { "loading" : true, "win" : objWin };

    return { "doc" : objWin.document, "kind" : "별도 팝업창", "url" : objWin.location.href };
}



// 실제로 열린 CSV 파일 선택 팝업창에서 렌더된 값을 읽어 출력한다.
//  · 별도 팝업창(기본)은 window 이름 csvupWindow 로 열리고, wframe 옵션 사용 시 화면 내 레이어로 열린다.
//  · popupUrl 적용 여부는 실제 열린 경로로, header/delim/startRowIndex 반영 여부는 팝업창의 입력 필드값으로 확인한다.
scwin.printUploadState = function (nRetry) {
    let bottom = wf_body_bottom.getObj("scwin");
    nRetry = nRetry || 0;

    let objInfo = scwin.getUploadDoc();

    if (objInfo !== null && objInfo.loading === true) {
        if (nRetry < 6) {
            setTimeout(function () { scwin.printUploadState(nRetry + 1); }, 500);
            return;
        }
        objInfo.win.close();
        objInfo = null;
    }

    if (objInfo === null) {
        bottom.setReturnValue("CSV 파일 선택 팝업창이 열려있지 않습니다.");
        return;
    }

    let objDoc = objInfo.doc;

    bottom.setReturnValue("팝업창 종류 : " + objInfo.kind + " / 실제 열린 경로 : " + objInfo.url);

    let objDelim = objDoc.querySelector("input[name='delim']");
    if (objDelim === null) {
        bottom.setReturnValue("엔진 기본 팝업창이 아니므로(커스텀 popupUrl) 업로드 옵션 필드가 존재하지 않습니다.");
        return;
    }

    bottom.setReturnValue("팝업창 렌더값 - delim : [" + objDelim.value + "] / header(Header 무시 여부) : [" + objDoc.querySelector("select[name='header']").value + "] / 데이터 시작 Row : [" + objDoc.querySelector("input[name='gridStartRow']").value + "]");
}



// 업로드 결과 확인 : GridView 에 실제 반영된 데이터와 바인딩된 DataList 의 데이터를 함께 출력한다.
scwin.btn_getResult_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.setReturnValue("=====btn_getResult_onclick=====");

    let cnt = target1.getRowCount();
    bottom.setReturnValue("GridView Row 수 : " + cnt + " / 바인딩 DataList Row 수 : " + dlt_bind.getRowCount());
    for (let i = 0; i < cnt; i++) {
        bottom.setReturnValue("[" + i + "] " + target1.getCellData(i, "col1") + " | " + target1.getCellData(i, "col2") + " | " + target1.getCellData(i, "col3") + " | " + target1.getCellData(i, "col4"));
    }
}



// 기본 서블릿 경로 확인 (@spec)
scwin.btn_getServletURL_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.setReturnValue("=====btn_getServletURL_onclick=====");
    bottom.setReturnValue("readCSV 기본 서블릿 : " + target1.options.csvUploadURL + " / saveCSV 기본 서블릿 : " + target1.options.csvDownloadURL);
}
